import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CNDaxUod.js";const p=JSON.parse('{"title":"Migrating to the JSON Resume structure in v0.4","description":"","frontmatter":{},"headers":[],"relativePath":"migrations/v0.4-json-resume.md","filePath":"migrations/v0.4-json-resume.md","lastUpdated":1788607300000}'),s={name:"migrations/v0.4-json-resume.md"};function n(d,e,r,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="migrating-to-the-json-resume-structure-in-v0-4" tabindex="-1">Migrating to the JSON Resume structure in v0.4 <a class="header-anchor" href="#migrating-to-the-json-resume-structure-in-v0-4" aria-label="Permalink to &quot;Migrating to the JSON Resume structure in v0.4&quot;">​</a></h1><p>Web Resume v0.4 adopts the JSON Resume field structure for new and converted documents. Existing YAML remains supported during the v0.4 migration period.</p><h2 id="delivered-in-v0-4" tabindex="-1">Delivered in v0.4 <a class="header-anchor" href="#delivered-in-v0-4" aria-label="Permalink to &quot;Delivered in v0.4&quot;">​</a></h2><ul><li>The canonical JSON Resume schema is pinned, with standard, legacy, and combined editor schemas published by the app.</li><li>Both formats are detected and validated against their own contracts.</li><li>Canonical documents render through an isolated adapter.</li><li>Editor conversion is explicit, reviewable, and undoable.</li><li>The CLI supports read-only checks and conversion to a separate output file.</li><li>Visual drag order is persisted in <code>x-web-resume.sectionOrder</code> for standard documents.</li><li>Portable export strips extensions and non-standard fields before canonical validation and download.</li><li>Built-in presets use the standard structure, with mixed employment, project, volunteer, award, and publication entries resolved by meaning.</li><li>The remaining canonical sections—volunteer, publications, languages, interests, and references—are rendered.</li><li>The target stable data contract is documented for the eventual v1.0 release.</li></ul><h2 id="compatibility-policy" tabindex="-1">Compatibility policy <a class="header-anchor" href="#compatibility-policy" aria-label="Permalink to &quot;Compatibility policy&quot;">​</a></h2><ul><li>Existing legacy YAML continues to load and render without being rewritten.</li><li>The editor detects legacy documents and offers an explicit conversion review.</li><li>Conversion only writes to the editor after confirmation and can be undone with the editor&#39;s normal undo command.</li><li>New standard documents may remain YAML; JSON Resume defines the data shape, not the authoring syntax used by Web Resume.</li><li>Presentation-only data is stored under the single <code>x-web-resume</code> extension.</li></ul><h2 id="main-field-changes" tabindex="-1">Main field changes <a class="header-anchor" href="#main-field-changes" aria-label="Permalink to &quot;Main field changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Legacy field</th><th>v0.4 field</th></tr></thead><tbody><tr><td><code>basics.avatar</code></td><td><code>basics.image</code></td></tr><tr><td><code>basics.bio</code></td><td><code>basics.summary</code></td></tr><tr><td><code>contact.email</code></td><td><code>basics.email</code></td></tr><tr><td><code>contact.phone</code></td><td><code>basics.phone</code></td></tr><tr><td><code>contact.blog</code></td><td><code>basics.url</code></td></tr><tr><td>other <code>contact.*</code></td><td><code>basics.profiles[]</code></td></tr><tr><td><code>education.histories[]</code></td><td><code>education[]</code></td></tr><tr><td><code>work.sets[]</code></td><td><code>work[]</code></td></tr><tr><td><code>project.sets[]</code></td><td><code>projects[]</code></td></tr><tr><td><code>skill.sets[]</code></td><td><code>skills[]</code></td></tr><tr><td><code>certificate.histories[]</code></td><td><code>awards[]</code>, followed by manual review</td></tr><tr><td><code>start</code> / <code>end</code></td><td><code>startDate</code> / <code>endDate</code></td></tr></tbody></table><p>Section titles, icons, item logos, expanded state, badges, custom profile details, the <code>other</code> section, and display order move to <code>x-web-resume</code>.</p><h2 id="editor-conversion" tabindex="-1">Editor conversion <a class="header-anchor" href="#editor-conversion" aria-label="Permalink to &quot;Editor conversion&quot;">​</a></h2><p>Open a legacy document in the editor and choose <strong>Review and convert</strong>. The review lists fields that need attention. Confirming replaces the editor content but does not alter the originally loaded URL or file. Use Undo immediately to restore the previous text.</p><p>The converter does not silently guess when:</p><ul><li>a legacy <code>project</code> is actually employment;</li><li>an entry under <code>certificate</code> is an award, certificate, or publication;</li><li>a free-form location cannot be split into structured address fields;</li><li>a localized or ranged date cannot be represented as <code>YYYY</code>, <code>YYYY-MM</code>, or <code>YYYY-MM-DD</code>.</li></ul><p>Values that cannot be represented safely are retained in <code>x-web-resume</code> and reported as warnings. YAML comments are reported separately because the current conversion serializer cannot preserve them.</p><p>Unknown fields are retained under <code>x-web-resume.legacyFields</code>. Each key is the field&#39;s original <a href="https://www.rfc-editor.org/rfc/rfc6901" target="_blank" rel="noreferrer">JSON Pointer</a> path, so custom data remains recoverable without duplicating the complete legacy document.</p><h2 id="cli-conversion" tabindex="-1">CLI conversion <a class="header-anchor" href="#cli-conversion" aria-label="Permalink to &quot;CLI conversion&quot;">​</a></h2><p>Check a file without writing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>The check exits successfully for a valid standard document and with status <code>1</code> when a legacy document needs migration or validation fails.</p><p>Write a converted copy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate:resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./resume.v0.4.yml</span></span></code></pre></div><p>The CLI never overwrites the input implicitly. Review the warnings and diff before replacing the original file.</p><h2 id="schema-urls" tabindex="-1">Schema URLs <a class="header-anchor" href="#schema-urls" aria-label="Permalink to &quot;Schema URLs&quot;">​</a></h2><ul><li><code>/schema/resume.schema.json</code>: combined editor schema accepting standard and legacy documents during v0.4.</li><li><code>/schema/json-resume.schema.json</code>: the pinned canonical JSON Resume schema bundled with the app.</li><li><code>/schema/resume-legacy.schema.json</code>: the previous Web Resume data contract.</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Before conversion, keep the source file or commit it to version control. In the browser, conversion is a single undoable editor operation. For CLI conversion, the input remains untouched unless you replace it yourself.</p><p>Legacy reading will not be removed during v0.4. Any future removal must be announced as part of the stable <code>1.0.0</code> data contract and include a tested migration path.</p><p>The target stable contract is documented in <a href="./../reference/data-contract-v1">Data contract for v1</a>.</p>',28)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
